#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>
std::vector<std::size_t> RotationStarts(const std::string& a, const std::string& b) {
    static_assert('A' == 65 && 'Z' == 90, "ASCII required");
    for (const auto* s : {&a, &b}) {
        if (s->size() > 1000) throw std::invalid_argument("too long");
        for (unsigned char c : *s)
            if (c < 'A' || c > 'Z') throw std::invalid_argument("not uppercase ASCII");
    }
    std::vector<std::size_t> result;
    if (a.size() != b.size()) return result;
    if (a.empty()) { result.push_back(0); return result; }
    // 각 시작점을 오름차순으로 한 번씩 검사합니다.
    for (std::size_t k = 0; k < a.size(); ++k) {
        bool same = true;
        for (std::size_t j = 0; j < a.size(); ++j)
            if (a[(k + j) % a.size()] != b[j]) { same = false; break; }
        if (same) result.push_back(k);
    }
    return result;
}
int main() {
    std::size_t cases = 0;
    // 길이 0~6의 A/B 기록 모든 쌍을 실제 문자열 회전과 대조합니다.
    for (std::size_t n = 0; n <= 6; ++n)
        for (unsigned x = 0; x < (1u << n); ++x)
            for (unsigned y = 0; y < (1u << n); ++y) {
                std::string a(n, 'A'), b(n, 'A');
                for (std::size_t i = 0; i < n; ++i) {
                    if (x & (1u << i)) a[i] = 'B';
                    if (y & (1u << i)) b[i] = 'B';
                }
                std::vector<std::size_t> expected;
                if (n == 0) expected.push_back(0);
                for (std::size_t k = 0; k < n; ++k)
                    if (a.substr(k) + a.substr(0, k) == b) expected.push_back(k);
                assert(RotationStarts(a, b) == expected); ++cases;
            }
    assert(RotationStarts("A", "AB").empty());
    bool caught = false;
    try { RotationStarts(std::string("A\0B", 3), "ABC"); }
    catch (const std::invalid_argument&) { caught = true; }
    assert(caught);
    std::cout << "rotation pairs: " << cases << ", invalid input: passed\n";
}
